   "isHistorical": true,
   "sid": "sc-jianyan1-1127-shaosong",
   "officialTitle": "金·尚书右仆射(汉相)",
   "role": "金臣(汉)",
   "age": 46,
   "stance": "金初汉相·建汉制",
   "location": "燕京·会宁",
   "bio": "燕地汉人，金初名相，定官制、收人才，金朝汉化典制多出其手。",
   "id": "char_ss_180",
   "faith": "儒·释·道",
   "culture": "汉",
   "active": true,
   "presenceState": "present",
   "isPlayer": false,
   "type": "historical",
   "isFictional": false,
   "rankLevel": 3,
   "management": 79,
